// AuthMutationServer is the server API for AuthMutation service.
// All implementations should embed UnimplementedAuthMutationServer
// for forward compatibility.
type AuthMutationServer interface {
	// CreateUser — INSERT User. The `password_hash` request
	// field carries the already-encoded hash — the plugin's
	// AuthService.SignUp handler computes it via
	// passwordhash.Settings.Hash() before calling. Refuses on
	// duplicate email (unique violation surfaces as
	// AlreadyExists via REV-026 DB-error classification).
	//
	// ONE create for every activation. `tenant_scope` adds a NOT NULL
	// `User.tenant_id`, and the gated SET assignment below writes it, so
	// the feature no longer has to REPLACE this method.
	//
	// It used to. The feature filter could not splice a column into a
	// fixed INSERT, so `tenant_scope` gated this rpc OUT
	// (`plugin_feature_rpc_unless`) and a twin — CreateUserWithTenant —
	// took over. That duplication cost an event: an event has exactly one
	// emit site, the baseline owned it, and the baseline was the one being
	// filtered away, so with `tenant_scope` on `UserCreated` had NO
	// emitter and every subscriber to auth.user.created silently never
	// fired. See docs/decisions/dql-feature-gated-fragments.md.
	// CreateBot — insert a machine account. kind = BOT (1), no password.
	CreateBotUser(context.Context, *CreateBotUserReq) (*CreateBotUserResp, error)
	CreateUser(context.Context, *CreateUserReq) (*CreateUserResp, error)
	// IssueToken — INSERT UserToken. The `token` column fills
	// app-side via the CRYPTO_RANDOM default (Phase N) — request
	// doesn't carry the token value; codegen preamble generates
	// it before SQL emit.
	IssueToken(context.Context, *IssueTokenReq) (*IssueTokenResp, error)
	// DeleteToken — DELETE matching token. Idempotent: no-such-
	// token returns OK with an empty response (RowsAffected = 0
	// is not an error for sign-out semantics).
	//
	// Token rotation is not a single-RPC primitive — consumer
	// composes it as GetUserByToken → DeleteToken → IssueToken
	// (3 calls, ~3 lines). DQL doesn't pass results between
	// query/mutation ops in the same RPC, so atomic rotation
	// can't be expressed in the current DSL; the time gap
	// between old-invalid and new-issued is irrelevant for
	// bearer-token semantics.
	// Does NOT emit TokenRevoked: the eventbus allows one emit site per
	// event, and DeleteSessionToken (the live, handler-driven logout path)
	// owns it. DeleteToken is an uncalled low-level primitive — emitting
	// here would be dead (never fires) and, in its documented rotation use
	// (GetUserByToken → DeleteToken → IssueToken), a misleading "revoked"
	// signal for what is really a rotation. The RETURNING ids stay for the
	// caller's response.
	DeleteToken(context.Context, *DeleteTokenReq) (*DeleteTokenResp, error)
	// DeleteSessionToken — base-tier logout primitive (gated
	// authenticate_turnkey). Delete-by-id, OWNERSHIP guarded (id AND
	// user_id) so a caller revokes only their own token. This is the SOLE
	// TokenRevoked emit site (the live logout path) so cache-invalidation
	// subscribers react on logout; DeleteToken no longer emits. Idempotent.
	//
	// Q64-auth-1: the DQL deliberately does NOT filter on token_type — that
	// column is gated by the `api_token` feature, so referencing it here (a
	// base-tier authenticate_turnkey mutation) breaks typecheck on the
	// default config where api_token is off and the column doesn't exist.
	// The type guard is unnecessary anyway: the Logout handler sources
	// token_id from the resolved session_token_id in the auth envelope
	// (callerSessionTokenID), which is populated ONLY for SESSION bearers
	// (an API-token bearer yields "" → idempotent no-op), so token_id is
	// always a session token. The retained req.token_type field is unused by
	// the DQL (kept for wire stability + the handler's explicit intent).
	DeleteSessionToken(context.Context, *DeleteSessionTokenReq) (*DeleteSessionTokenResp, error)
	// IssueApiToken — INSERT an API UserToken (token_type stamped by
	// the handler) with an optional label. token fills app-side via
	// CRYPTO_RANDOM. Gated api_token.
	IssueApiToken(context.Context, *IssueApiTokenReq) (*IssueApiTokenResp, error)
	// AddTokenPermission — INSERT a TokenPermission subset row.
	// Composite-unique (token_id, permission_id). Gated api_token.
	AddTokenPermission(context.Context, *AddTokenPermissionReq) (*AddTokenPermissionResp, error)
	// DeleteApiToken — DELETE the caller's own API token (ownership +
	// realm guarded: id AND user_id AND token_type all match, so a
	// bearer can't revoke another user's token or a session token via
	// this path). Idempotent. Gated api_token.
	DeleteApiToken(context.Context, *DeleteApiTokenReq) (*DeleteApiTokenResp, error)
	// DeleteTokenPermissions — DELETE every subset row for a token
	// (revoke cleanup, before/after DeleteApiToken). All deleted rows
	// share the same token_id, so the single response field is well-
	// defined. Idempotent. Gated api_token.
	DeleteTokenPermissions(context.Context, *DeleteTokenPermissionsReq) (*DeleteTokenPermissionsResp, error)
	// CreateOAuthIdentity — INSERT the User↔subject link on first OAuth
	// sign-in. Composite-unique (provider_id, external_id). Gated oauth.
	CreateOAuthIdentity(context.Context, *CreateOAuthIdentityReq) (*CreateOAuthIdentityResp, error)
	// CreateTotpSecret — INSERT a TOTP secret (confirmed_at NULL until the
	// first code verifies). Unique user_id → re-enroll refuses with
	// AlreadyExists (the handler deletes first to rotate). Emits TotpEnrolled.
	CreateTotpSecret(context.Context, *CreateTotpSecretReq) (*CreateTotpSecretResp, error)
	// ConfirmTotpSecret — mark the user's TOTP confirmed (the first code
	// verified). Now the user "has an authenticator". Emits TotpConfirmed.
	ConfirmTotpSecret(context.Context, *ConfirmTotpSecretReq) (*ConfirmTotpSecretResp, error)
	// DeleteTotpSecret — disable the built-in authenticator. Idempotent.
	// Emits TotpDisabled.
	DeleteTotpSecret(context.Context, *DeleteTotpSecretReq) (*DeleteTotpSecretResp, error)
	// CreateMfaChallenge — INSERT a pending challenge (code_hash empty for
	// the TOTP path; set for the event/fallback path). The INSERT binds
	// only :user_id + :code_hash; the request's event-only fields
	// (totp_enrolled / email / code / expires_at) feed the emit. Emits
	// MfaChallengeRequested on EVERY challenge — the keystone hook a hand-
	// written subscriber reads (totp_enrolled true → stay passive; false →
	// deliver `code` over SMS/e-mail).
	CreateMfaChallenge(context.Context, *CreateMfaChallengeReq) (*CreateMfaChallengeResp, error)
	// ConsumeMfaChallenge — mark a challenge used (single-use guard:
	// consumed_at IS NULL). RETURNING user_id is the proof of an actual
	// consume (empty → already used / not found). Emits MfaVerified.
	ConsumeMfaChallenge(context.Context, *ConsumeMfaChallengeReq) (*ConsumeMfaChallengeResp, error)
	// RecordMfaAttempt — atomically increment the challenge's failed-attempt
	// counter (Q43-auth-mfa). Guarded `consumed_at IS NULL` so a consumed
	// challenge isn't bumped; RETURNING the new count. No event (internal
	// brute-force guard, not a user-visible lifecycle step).
	RecordMfaAttempt(context.Context, *RecordMfaAttemptReq) (*RecordMfaAttemptResp, error)
	// CreateDevice — INSERT a Device on first sight of an
	// (user, identifier). last_seen_at / created_at fill via their
	// NOW defaults; trusted_at stays NULL until a login completes
	// (TrustDevice). Composite-unique (user_id, identifier) refuses a
	// racing duplicate with AlreadyExists; the handler re-reads.
	CreateDevice(context.Context, *CreateDeviceReq) (*CreateDeviceResp, error)
	// TrustDevice — mark the (user, identifier) device trusted +
	// refresh last_seen. Called when a login (or VerifyMfa) for the
	// device completes; the trusted_at it stamps is the signal
	// `two_factor` new-device mode reads to skip the challenge.
	TrustDevice(context.Context, *TrustDeviceReq) (*TrustDeviceResp, error)
	// TouchDevice — refresh last_seen (+ ip) without trusting. Used
	// when a new-device sign-in raises a 2FA challenge: the device is
	// seen but not yet trusted (trust waits for VerifyMfa). Idempotent.
	TouchDevice(context.Context, *TouchDeviceReq) (*TouchDeviceResp, error)
	// DeleteDeviceTokens — DELETE every session token a device owns
	// (the "log out this device" primitive). Ownership-guarded by
	// user_id so a caller can't drop another user's sessions.
	// Idempotent.
	DeleteDeviceTokens(context.Context, *DeleteDeviceTokensReq) (*DeleteDeviceTokensResp, error)
	// DeleteDevice — DELETE the Device row itself (after its tokens).
	// Ownership-guarded (id AND user_id). Idempotent.
	DeleteDevice(context.Context, *DeleteDeviceReq) (*DeleteDeviceResp, error)
	// DeleteAllUserTokens — DELETE every session token the user holds
	// ("log out everywhere", incl. the caller). Idempotent.
	DeleteAllUserTokens(context.Context, *DeleteAllUserTokensReq) (*DeleteAllUserTokensResp, error)
	// DeleteAllUserDevices — DELETE every Device the user holds
	// (revoke-all cleanup, after DeleteAllUserTokens). Idempotent.
	DeleteAllUserDevices(context.Context, *DeleteAllUserDevicesReq) (*DeleteAllUserDevicesResp, error)
	// CreateRole — INSERT Role. Refuses duplicate name (unique
	// violation → AlreadyExists via REV-026 DB-error classification).
	CreateRole(context.Context, *CreateRoleReq) (*CreateRoleResp, error)
	// DeleteRole — DELETE matching role. Idempotent. Caller
	// is responsible for cleaning up dependent UserRole /
	// RolePermission rows ahead of time (v1: no FK cascade —
	// the activation-rename FK limitation applies).
	// UpdateRole — the admin Roles page detail `update`. Copy only
	// (name + description); the privilege flags stay declarative, seeded
	// from `(w17.acl_roles)`, so an admin form can't widen a grant.
	// Gated rbac.
	UpdateRole(context.Context, *UpdateRoleReq) (*UpdateRoleResp, error)
	DeleteRole(context.Context, *DeleteRoleReq) (*DeleteRoleResp, error)
	// DeleteUser — hard-delete one account + its tokens (base UserToken;
	// always present) in one transaction, newest op is the response
	// producer. Emits UserDeleted for downstream cleanup of feature-owned
	// rows the plugin can't reference here (see the message comment).
	// Gated user_admin.
	// UpdateUser — the admin Users page detail `update`. Sets the email
	// only; password_hash stays with UpdateUserPassword (gated
	// password_reset) so credential material never rides an admin form.
	// Gated user_admin.
	UpdateUser(context.Context, *UpdateUserReq) (*UpdateUserResp, error)
	DeleteUser(context.Context, *DeleteUserReq) (*DeleteUserResp, error)
	// DisableUsers — bulk soft-disable (Django is_active=false). Sets
	// disabled_at on the still-active rows in the id set and returns the
	// ids it flipped. SignIn rejects a disabled account
	// (handlers/user_admin.go), but existing tokens survive until expiry
	// or revocation. Single-op: the `IN (:ids)` array bind must sit on the
	// FINAL op (the dialect-aware IN-expansion only runs there — a
	// non-final leg with `IN (:collection)` is refused, T2-6 F-A2). Gated
	// user_admin.
	DisableUsers(context.Context, *DisableUsersReq) (*DisableUsersResp, error)
	// EnableUsers — bulk re-enable (clear disabled_at); returns the ids it
	// re-enabled. Single-op for the same F-A2 reason as DisableUsers.
	// Gated user_admin.
	EnableUsers(context.Context, *EnableUsersReq) (*EnableUsersResp, error)
	// AssignRoleToUser — INSERT UserRole linking a user to a
	// role. Composite-unique (user_id, role_id) refuses duplicate
	// assignments with AlreadyExists.
	AssignRoleToUser(context.Context, *AssignRoleToUserReq) (*AssignRoleToUserResp, error)
	// RevokeRoleFromUser — DELETE matching UserRole row.
	// Idempotent.
	RevokeRoleFromUser(context.Context, *RevokeRoleFromUserReq) (*RevokeRoleFromUserResp, error)
	// AddPermissionToRole — INSERT RolePermission linking a
	// permission to a role. Composite-unique (role_id,
	// permission_id) refuses duplicate grants.
	AddPermissionToRole(context.Context, *AddPermissionToRoleReq) (*AddPermissionToRoleResp, error)
	// RemovePermissionFromRole — DELETE matching RolePermission
	// row. Idempotent.
	RemovePermissionFromRole(context.Context, *RemovePermissionFromRoleReq) (*RemovePermissionFromRoleResp, error)
	// CreatePasswordResetToken — INSERT the hashed reset token + expiry and
	// emit PasswordResetRequested carrying the plaintext token + email (the
	// INSERT binds only the persisted columns; the plaintext is event-only).
	CreatePasswordResetToken(context.Context, *CreatePasswordResetTokenReq) (*CreatePasswordResetTokenResp, error)
	// ConsumePasswordResetToken — atomically claim a live token: flip
	// consumed_at single-use AND require not-yet-consumed + not-expired in
	// the WHERE, so a replay / expired / already-used token matches zero rows
	// (empty user_id). No TOCTOU between validate + consume.
	ConsumePasswordResetToken(context.Context, *ConsumePasswordResetTokenReq) (*ConsumePasswordResetTokenResp, error)
	// UpdateUserPassword — apply a reset: set the user's password_hash.
	UpdateUserPassword(context.Context, *UpdateUserPasswordReq) (*UpdateUserPasswordResp, error)
	// UpdateUserPasswordIfUnchanged — apply a CHANGE: set the password_hash
	// only while the stored one is still the value the caller's proof was
	// verified against.
	//
	// Separate from UpdateUserPassword rather than a predicate added to it,
	// because that one also serves the RESET flow — where the whole premise is
	// that nobody knows the current password, so there is no hash to compare
	// and a predicate would make every reset match zero rows.
	//
	// Same shape as ConsumePasswordResetToken above, for the same reason: the
	// check and the write are one statement, so nothing can change underneath
	// between them. ChangePassword otherwise reads the hash, verifies it, and
	// writes — with an argon2id hash computed in the middle, which is tens of
	// milliseconds of window BY DESIGN. Last write wins there, so a victim's
	// fresh rotation can be overwritten by an attacker who knew the old
	// password, and two honest tabs silently lose one of the two changes.
	UpdateUserPasswordIfUnchanged(context.Context, *UpdateUserPasswordIfUnchangedReq) (*UpdateUserPasswordIfUnchangedResp, error)
	// DeleteUserSessionsForReset — revoke every token for the user after a
	// reset (sessions + API tokens; the conservative post-reset default).
	DeleteUserSessionsForReset(context.Context, *DeleteUserSessionsForResetReq) (*DeleteUserSessionsForResetResp, error)
	CreateEmailVerificationToken(context.Context, *CreateEmailVerificationTokenReq) (*CreateEmailVerificationTokenResp, error)
	ConsumeEmailVerificationToken(context.Context, *ConsumeEmailVerificationTokenReq) (*ConsumeEmailVerificationTokenResp, error)
	// MarkEmailVerified — stamp the user's email_verified_at.
	MarkEmailVerified(context.Context, *MarkEmailVerifiedReq) (*MarkEmailVerifiedResp, error)
	// CreateCliAuthCode — INSERT a single-use PKCE code bound to the
	// approving user + challenge (only the hash is stored).
	CreateCliAuthCode(context.Context, *CreateCliAuthCodeReq) (*CreateCliAuthCodeResp, error)
	// ConsumeCliAuthCode — atomically claim a live code: flip consumed_at
	// single-use AND require not-consumed + not-expired in the WHERE, so a
	// replay / expired / used code matches zero rows (empty user_id). No
	// TOCTOU between validate + consume.
	ConsumeCliAuthCode(context.Context, *ConsumeCliAuthCodeReq) (*ConsumeCliAuthCodeResp, error)
	// CreateOrganization — INSERT Organization. Refuses a duplicate slug
	// (unique violation → AlreadyExists via REV-026 DB-error
	// classification). Emits OrganizationCreated — the keystone
	// provisioning hook (a subscriber seeds the org's default data off
	// org_id) so a project never has to INSERT into this plugin's tables
	// directly.
	CreateOrganization(context.Context, *CreateOrganizationReq) (*CreateOrganizationResp, error)
	// AddOrgMembership — INSERT OrgMembership linking a user to an org
	// with a role. Composite-unique (user_id, org_id) refuses a duplicate
	// membership with AlreadyExists. Emits OrgMembershipAdded (fires for
	// the creator's owner grant + every later invite accept). Mirrors
	// AssignRoleToUser.
	AddOrgMembership(context.Context, *AddOrgMembershipReq) (*AddOrgMembershipResp, error)
	// DeleteOrganization — the admin Organizations page delete. Purges the
	// org's memberships first (link table, app-enforced — no DB FK, same
	// caveat as the rest of the plugin), then the org, atomically. The
	// membership purge is a NON-final leg (scalar :id bind — no array
	// expansion, so the F-A2 final-leg rule doesn't apply). Emits
	// OrganizationDeleted for downstream per-org cleanup. Gated
	// org_membership.
	// UpdateOrganization — the admin Organizations page detail `update`.
	// Gated org_membership.
	UpdateOrganization(context.Context, *UpdateOrganizationReq) (*UpdateOrganizationResp, error)
	DeleteOrganization(context.Context, *DeleteOrganizationReq) (*DeleteOrganizationResp, error)
	// DeleteOrgMembership — the admin OrgMemberships page delete: remove
	// one membership row (revoke a user's place in an org). Emits
	// OrgMembershipRemoved. Gated org_membership.
	// UpdateOrgMembership — the admin OrgMemberships page detail
	// `update`. Role only: re-pointing a membership at a different user
	// or org is a delete + re-add, not an edit (the unique
	// (user_id, org_id) index makes an in-place move a constraint trap).
	// Gated org_membership.
	UpdateOrgMembership(context.Context, *UpdateOrgMembershipReq) (*UpdateOrgMembershipResp, error)
	DeleteOrgMembership(context.Context, *DeleteOrgMembershipReq) (*DeleteOrgMembershipResp, error)
	// RevokeUserToken — the admin Sessions page delete: hard-remove one
	// token so that session/API bearer stops authenticating immediately.
	// Emits UserTokenRevoked. Gated user_admin.
	RevokeUserToken(context.Context, *RevokeUserTokenReq) (*RevokeUserTokenResp, error)
	// CreateOrgInvite — record a pending invitation. The partial unique
	// index on (org_id, email) WHERE accepted_at IS NULL is what makes a
	// second pending invite for the same address a database refusal rather
	// than a duplicate row two admins race to create; a CONSUMED invite does
	// not block a later one, because being removed from an org and invited
	// back is a normal thing to happen.
	CreateOrgInvite(context.Context, *CreateOrgInviteReq) (*CreateOrgInviteResp, error)
	// ClearExpiredOrgInvite — release the slot an EXPIRED invitation holds.
	//
	// The pending-invite index is unique on (org_id, email) WHERE accepted_at
	// IS NULL, and it cannot say "and not expired": a partial index predicate
	// must be IMMUTABLE, and `NOW()` is not. So an invitation that lapsed still
	// occupies the pair, and re-inviting the same address fails on a unique
	// violation whose message reads like two people racing — when in fact
	// nobody is, and the blocker is a row the inviter can see in their own
	// list and cannot get past.
	//
	// Expired only. A LIVE invitation must still block a second one: that
	// refusal is correct and is what stops two roles being offered to one
	// address at once.
	//
	// Zero rows is the ordinary case — nothing has lapsed — and arrives as
	// NOT_FOUND because of the RETURNING. The caller treats it as "nothing to
	// clear" rather than as a failure.
	ClearExpiredOrgInvite(context.Context, *ClearExpiredOrgInviteReq) (*ClearExpiredOrgInviteResp, error)
	// MarkOrgInviteAccepted — claim a live invitation, single-use, in ONE
	// statement. The not-yet-accepted and not-expired tests sit in the
	// WHERE beside the write, exactly as ConsumePasswordResetToken does, so
	// there is no window between checking an invitation and consuming it.
	// A replayed, expired or already-accepted invite matches zero rows and
	// comes back with an empty org_id.
	MarkOrgInviteAccepted(context.Context, *MarkOrgInviteAcceptedReq) (*MarkOrgInviteAcceptedResp, error)
	// DeleteOrgInvite — withdraw a PENDING invitation. Scoped by org_id in
	// the WHERE and not only by id: the handler already knows the caller's
	// active org, and an id-only delete would let a member of one
	// organization revoke another's invitation by guessing a uuid.
	DeleteOrgInvite(context.Context, *DeleteOrgInviteReq) (*DeleteOrgInviteResp, error)
}

